import { DURATION_BY_DATE_FILTER } from "../helpers/FilterHelper";
import { DateFilter } from "../types";
import { subtractDate } from "./date";

const when = new Date("2024-05-15T12:00:00Z");

describe("DateFilter enum (trial T3, turn 1)", () => {
  it("is an enum with the same values", () => {
    expect(DateFilter.Day).toBe("day");
    expect(DateFilter.Week).toBe("week");
    expect(DateFilter.Month).toBe("month");
    expect(DateFilter.Year).toBe("year");
  });

  it("still works where it is used", () => {
    expect(subtractDate(when, DateFilter.Week).toISOString()).toBe("2024-05-08T12:00:00.000Z");
    expect(DURATION_BY_DATE_FILTER[DateFilter.Year]).toBe("-P1Y");
  });
});

import { DURATION_BY_DATE_FILTER } from "../helpers/FilterHelper";
import { DateFilter } from "../types";
import { subtractDate } from "./date";

const when = new Date("2024-05-15T12:00:00Z");

describe("DateFilter.Quarter (trial T3, turn 2)", () => {
  it("is three months", () => {
    expect(DateFilter.Quarter).toBe("quarter");
    expect(subtractDate(when, DateFilter.Quarter).toISOString()).toBe("2024-02-15T12:00:00.000Z");
    expect(DURATION_BY_DATE_FILTER[DateFilter.Quarter]).toBe("-P3M");
  });
});
